llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Ribavirin, the closest D-ribofuranosyl analogue sharing the carboxamide and ribose stereochemistry, has an absolute oral bioavailability of 52% in patients, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Levovirin, the L-ribose enantiomer of ribavirin, has only ~10% oral bioavailability, but its L-stereochemistry prevents transporter-mediated absorption; this is not transferable to the D-ribose query and does not outweigh the D-nucleoside evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Fludarabine, a D-ribose purine nucleoside analog, shows approximately 55% oral bioavailability, supporting the pattern that polar D-nucleosides can exceed 20% via active uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Clofarabine, another D-ribose purine nucleoside analog, has an oral bioavailability of 57.5%, further supporting that the query's D-ribose nucleoside scaffold can achieve F ≥ 20% despite high polarity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a D-ribofuranosyl nucleoside analog most closely related to ribavirin, which has F ~50% in humans. Multiple other D-ribose nucleoside analogs (fludarabine, cladribine, clofarabine) also exceed 20%, indicating transporter-mediated absorption can overcome the polar physicochemical prior. The low-F examples are either L-nucleosides (levovirin) or structurally more distant pyrimidines (uridine, NHC), so they do not override. Prediction: high.",
  "evidence_gaps": [
    "No direct oral bioavailability data for AICAR itself; uncertainty remains about whether the 5-amino group alters transporter affinity or metabolic stability relative to ribavirin.",
    "First-pass metabolism and formulation effects are not directly assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

